begin;
alter table public.business_types add column game_family text not null default 'sales' check(game_family in('technology','food','transport','quality','sales','logistics','health','finance')),
 add column base_daily_capacity numeric not null default 10 check(base_daily_capacity>0),
 add column daily_overhead numeric not null default 10 check(daily_overhead>=0);
create table public.economic_resources(code text primary key,name text not null,unit text not null,base_price numeric not null check(base_price>0),is_service boolean not null default false);
create table public.business_recipes(id text primary key,business_type_id text not null references public.business_types(id),output_resource text not null references public.economic_resources(code),output_quantity numeric not null default 1 check(output_quantity>0),inputs jsonb not null default '{}');
create table public.business_role_templates(id text primary key,business_type_id text not null references public.business_types(id),name text not null,skill_area text not null,game_family text not null,base_weekly_salary numeric not null check(base_weekly_salary>0),can_manage boolean not null default false);
create table public.business_inventory(business_id uuid not null references public.businesses(id),resource_code text not null references public.economic_resources(code),quantity numeric not null default 0 check(quantity>=0),unit_cost numeric not null default 0 check(unit_cost>=0),selling_price numeric check(selling_price>0),available_for_sale boolean not null default false,updated_at timestamptz not null default now(),primary key(business_id,resource_code));
alter table public.businesses alter column owner_id drop not null;
alter table public.businesses add column control_kind text not null default 'player' check(control_kind in('player','population')),
 add column owner_operates boolean not null default true, add column market_value numeric not null default 0 check(market_value>=0),
 add column size_class text not null default 'micro' check(size_class in('micro','small','medium','large','national')),
 add column reputation numeric not null default 50 check(reputation between 0 and 100),
 add column operational_status text not null default 'starting' check(operational_status in('starting','operating','understaffed','missing_inputs','cash_shortage','insolvent','closed')),
 add column loss_cycles integer not null default 0 check(loss_cycles>=0),
 add column price_multiplier numeric not null default 1 check(price_multiplier between .5 and 3),
 add column last_simulated_on date, add column last_fiscal_cycle_at timestamptz not null default now();
alter table public.businesses add constraint businesses_controller_check check((control_kind='player' and owner_id is not null) or (control_kind='population' and owner_id is null));
alter table public.business_employees add column role_template_id text references public.business_role_templates(id),
 add column skill_area text not null default 'management', add column experience integer not null default 0 check(experience>=0),
 add column satisfaction numeric not null default 70 check(satisfaction between 0 and 100),
 add column wage_due numeric not null default 0 check(wage_due>=0),
 add column last_accrued_on date, add column last_paid_at timestamptz,
 add column qualification_level integer not null default 1 check(qualification_level between 1 and 20);
-- Preserve legacy staff history while ensuring one active paid employment per citizen.
with duplicated as(select id,row_number() over(partition by profile_id order by hired_at,id) n from public.business_employees where profile_id is not null and fired_at is null)
update public.business_employees set fired_at=now() where id in(select id from duplicated where n>1);
create unique index one_citizen_primary_job on public.business_employees(profile_id) where profile_id is not null and fired_at is null;
create table public.citizen_professional_experience(profile_id uuid not null references public.profiles(id),skill_area text not null,experience integer not null default 0 check(experience>=0),updated_at timestamptz not null default now(),primary key(profile_id,skill_area));
create table public.business_vacancies(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),role_template_id text not null references public.business_role_templates(id),salary numeric not null check(salary>0 and salary<=100000000),min_level integer not null default 1 check(min_level between 1 and 20),positions integer not null default 1 check(positions between 0 and 100),description text not null default '',status text not null default 'open' check(status in('open','closed')),created_at timestamptz not null default now());
create table public.business_applications(id uuid primary key default gen_random_uuid(),vacancy_id uuid not null references public.business_vacancies(id),profile_id uuid not null references public.profiles(id),message text not null default '',status text not null default 'pending' check(status in('pending','accepted','rejected','withdrawn')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(vacancy_id,profile_id));
create table private.company_operations(idempotency_key uuid primary key,actor_id uuid not null,operation text not null,payload jsonb not null,result jsonb not null,created_at timestamptz not null default now());
revoke all on private.company_operations from public,anon,authenticated;
update public.businesses b set economic_sector_id=coalesce(b.economic_sector_id,t.economic_sector_id) from public.business_types t where t.id=b.business_type_id;
create or replace function private.can_manage_company(p_business_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path='' as $$
 select p_user_id is not null and (exists(select 1 from public.businesses where id=p_business_id and owner_id=p_user_id) or exists(select 1 from public.business_employees e join public.business_role_templates t on t.id=e.role_template_id where e.business_id=p_business_id and e.profile_id=p_user_id and e.fired_at is null and t.can_manage))
$$;
-- Sensitive fields and staff operations are changed only by authenticated RPCs.
revoke insert,update,delete on public.business_employees from authenticated,anon;
create or replace function private.protect_company_registration() returns trigger language plpgsql set search_path='' as $$
begin
 if current_user in('authenticated','anon') and (to_jsonb(new)-array['name','description','logo_url','font_key','brand_color','is_for_sale','sale_price','sale_listed_at','updated_at']) is distinct from (to_jsonb(old)-array['name','description','logo_url','font_key','brand_color','is_for_sale','sale_price','sale_listed_at','updated_at']) then raise exception 'Use a operação oficial para alterar dados de gestão da empresa.' using errcode='42501';end if;
 return new;
end $$;
alter table public.economic_resources enable row level security;
alter table public.business_recipes enable row level security;
alter table public.business_role_templates enable row level security;
alter table public.business_inventory enable row level security;
alter table public.citizen_professional_experience enable row level security;
alter table public.business_vacancies enable row level security;
alter table public.business_applications enable row level security;
create policy resources_read on public.economic_resources for select to authenticated using(true);
create policy recipes_read on public.business_recipes for select to authenticated using(true);
create policy company_roles_read on public.business_role_templates for select to authenticated using(true);
create policy company_inventory_read on public.business_inventory for select to authenticated using(private.can_manage_company(business_id));
create policy professional_experience_read on public.citizen_professional_experience for select to authenticated using(profile_id=(select auth.uid()));
create policy vacancies_read on public.business_vacancies for select to authenticated using(status='open' or private.can_manage_company(business_id));
create policy applications_read on public.business_applications for select to authenticated using(profile_id=(select auth.uid()) or exists(select 1 from public.business_vacancies v where v.id=vacancy_id and private.can_manage_company(v.business_id)));
create policy employee_own_read on public.business_employees for select to authenticated using(profile_id=(select auth.uid()) or private.can_manage_company(business_id));
create policy company_managers_read on public.businesses for select to authenticated using(private.can_manage_company(id));
revoke all on public.economic_resources,public.business_recipes,public.business_role_templates,public.business_inventory,public.citizen_professional_experience,public.business_vacancies,public.business_applications from anon,authenticated;
grant select on public.economic_resources,public.business_recipes,public.business_role_templates,public.business_inventory,public.citizen_professional_experience,public.business_vacancies,public.business_applications to authenticated;
create or replace function public.manage_company_workforce(p_business_id uuid,p_action text,p_data jsonb,p_idempotency_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare b public.businesses%rowtype; t public.business_role_templates%rowtype; e public.business_employees%rowtype; v public.business_vacancies%rowtype; application public.business_applications%rowtype; oldop private.company_operations%rowtype; result jsonb; target uuid; level integer; wage numeric; xp integer; person_name text; is_owner boolean; payload jsonb:=jsonb_build_object('business_id',p_business_id,'action',p_action,'data',p_data);
begin
 if auth.uid() is null or p_idempotency_key is null then raise exception 'Entre e identifique a operação de trabalho.' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into oldop from private.company_operations where idempotency_key=p_idempotency_key;
 if found then
  if oldop.actor_id<>auth.uid() or oldop.operation<>'workforce' or oldop.payload<>payload then raise exception 'Esta identificação já pertence a outra operação.';end if;
  return oldop.result;
 end if;
 select * into b from public.businesses where id=p_business_id for update;
 if b.id is null then raise exception 'Empresa indisponível.';end if;
 is_owner:=b.owner_id=auth.uid();
 if p_action<>'quit' and not private.can_manage_company(b.id) then raise exception 'Somente o proprietário ou gestor pode administrar a equipe.' using errcode='42501';end if;
 if p_action in('open_vacancy','hire_npc','change') then
  select * into t from public.business_role_templates where id=p_data->>'role_template_id' and business_type_id=b.business_type_id;
  if t.id is null then raise exception 'Escolha uma função compatível com a atividade da empresa.';end if;
  if t.can_manage and not is_owner then raise exception 'Somente o proprietário pode nomear gestores.' using errcode='42501';end if;
  wage:=(p_data->>'salary')::numeric;
  if wage is null or wage<t.base_weekly_salary or wage>100000000 or wage<>round(wage,2) then raise exception 'O salário semanal deve respeitar o mínimo da função e ter até duas casas decimais.';end if;
 end if;
 if p_action='open_vacancy' then
  level:=coalesce((p_data->>'min_level')::integer,1);
  if level not between 1 and 20 or coalesce((p_data->>'positions')::integer,0) not between 1 and 100 then raise exception 'Confira o nível mínimo e a quantidade de vagas.';end if;
 elsif p_action='close_vacancy' then
  update public.business_vacancies set status='closed' where id=(p_data->>'vacancy_id')::uuid and business_id=b.id returning id into target;
  if target is null then raise exception 'Vaga não encontrada nesta empresa.';end if;
 elsif p_action='hire_npc' then
  if b.status in('closed','suspended') then raise exception 'Regularize a empresa antes de contratar.';end if;
  level:=coalesce((p_data->>'level')::integer,1);
  if level not in(1,3,5) then raise exception 'Escolha uma das qualificações disponíveis da população.';end if;
  if wage<round(t.base_weekly_salary*(1+(level-1)*.08),2) then raise exception 'O salário oferecido está abaixo da expectativa desta qualificação.';end if;
  if (select count(*) from public.business_employees where business_id=b.id and fired_at is null)>=500 then raise exception 'O limite operacional desta unidade é de 500 trabalhadores.';end if;
  person_name:=(array['Ana','Bruno','Carla','Diego','Elisa','Felipe','Gabriela','Henrique'])[1+abs(hashtext(p_idempotency_key::text)::bigint)%8]||' '||(array['Silva','Santos','Oliveira','Souza','Lima','Costa','Pereira','Almeida'])[1+abs(hashtext(b.id::text||p_idempotency_key)::bigint)%8];
 elsif p_action in('accept','reject') then
  select * into application from public.business_applications where id=(p_data->>'application_id')::uuid for update;
  select * into v from public.business_vacancies where id=application.vacancy_id and business_id=b.id for update;
  if application.id is null or application.status<>'pending' or v.id is null then raise exception 'Candidatura indisponível nesta empresa.';end if;
  if p_action='accept' then
   if v.status<>'open' or v.positions<=0 or b.status in('closed','suspended') then raise exception 'Esta vaga já foi encerrada.';end if;
   select * into t from public.business_role_templates where id=v.role_template_id;
   if t.can_manage and not is_owner then raise exception 'Somente o proprietário pode contratar gestores.';end if;
   perform id from public.profiles where id=application.profile_id for update;
   if exists(select 1 from public.business_employees where profile_id=application.profile_id and fired_at is null) then raise exception 'Este cidadão já tem um emprego principal. Ele precisa encerrar o vínculo anterior.';end if;
   select coalesce(experience,0) into xp from public.citizen_professional_experience where profile_id=application.profile_id and skill_area=t.skill_area;
   level:=least(20,1+coalesce(xp,0)/100);
   if level<v.min_level then raise exception 'A experiência atual ainda não atende ao nível mínimo da vaga.';end if;
   select full_name into person_name from public.profiles where id=application.profile_id and deleted_at is null and onboarding_completed;
   if person_name is null then raise exception 'O cadastro deste candidato está indisponível.';end if;
   update public.business_vacancies set positions=positions-1,status=case when positions=1 then 'closed' else status end where id=v.id;
   update public.business_applications set status='accepted',updated_at=now() where id=application.id;
   update public.business_applications set status='withdrawn',updated_at=now() where profile_id=application.profile_id and status='pending';
  else
   update public.business_applications set status='rejected',updated_at=now() where id=application.id;
   target:=application.id;
  end if;
 elsif p_action in('change','fire','quit') then
  select * into e from public.business_employees where id=(p_data->>'employee_id')::uuid and business_id=b.id and fired_at is null for update;
  if e.id is null then raise exception 'Vínculo de trabalho indisponível.';end if;
  if p_action='quit' then
   if e.profile_id is distinct from auth.uid() then raise exception 'Você só pode encerrar o próprio vínculo.' using errcode='42501';end if;
  elsif not is_owner and (e.profile_id=auth.uid() or exists(select 1 from public.business_role_templates where id=e.role_template_id and can_manage)) then raise exception 'Somente o proprietário pode alterar o vínculo de um gestor.' using errcode='42501';end if;
  -- Accrue completed days at the previous salary before changing/ending the employment.
  update public.business_employees set wage_due=wage_due+round(e.salary/7*greatest(0,current_date-coalesce(e.last_accrued_on,e.hired_at::date)),2),last_accrued_on=current_date where id=e.id;
  if p_action='change' then
   update public.business_employees set role_template_id=t.id,role=t.name,skill_area=t.skill_area,salary=wage where id=e.id;
  else update public.business_employees set fired_at=now() where id=e.id;end if;
  target:=e.id;
  if e.profile_id is not null then insert into public.notifications(user_id,type,content,link) values(e.profile_id,'company_employment_changed',case when p_action='change' then 'Sua função ou remuneração em '||b.name||' foi atualizada.' else 'Seu vínculo com '||b.name||' foi encerrado. Valores devidos permanecem registrados.' end,'/services/my-work');end if;
 else raise exception 'Escolha uma ação válida de gestão de equipe.';end if;
 update public.businesses set employees=(select count(*) from public.business_employees where business_id=b.id and fired_at is null),updated_at=now() where id=b.id;
 result:=jsonb_build_object('success',true,'id',target);
 return result;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'Confira os números e identificações da operação.';
end $$;
create or replace function public.apply_company_vacancy(p_vacancy_id uuid,p_message text default '') returns uuid language plpgsql security definer set search_path='' as $$
declare v public.business_vacancies%rowtype; aid uuid;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and onboarding_completed and deleted_at is null) then raise exception 'Conclua sua cidadania antes de se candidatar.' using errcode='42501';end if;
 select * into v from public.business_vacancies where id=p_vacancy_id and status='open' for share;
 if v.id is null then raise exception 'Esta vaga não está mais disponível.';end if;
 if exists(select 1 from public.businesses where id=v.business_id and owner_id=auth.uid()) then raise exception 'O proprietário administra sua empresa pelo painel de gestão.';end if;
 if exists(select 1 from public.business_employees where profile_id=auth.uid() and fired_at is null) then raise exception 'Você já possui um emprego principal. Encerre o vínculo atual antes de se candidatar.';end if;
 return aid;
end $$;
create or replace function public.get_company_jobs() returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'business_id',b.id,'company_name',b.name,'logo_url',b.logo_url,'region_code',b.region_code,'role',t.name,'skill_area',t.skill_area,'salary',v.salary,'min_level',v.min_level,'positions',v.positions,'description',v.description,'created_at',v.created_at,'applied',exists(select 1 from public.business_applications a where a.vacancy_id=v.id and a.profile_id=auth.uid())) order by v.created_at desc),'[]'::jsonb)
 from public.business_vacancies v join public.businesses b on b.id=v.business_id join public.business_role_templates t on t.id=v.role_template_id where auth.uid() is not null and v.status='open' and b.status not in('closed','suspended')
$$;
create or replace function public.get_my_work() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('employments',coalesce((select jsonb_agg(to_jsonb(e)||jsonb_build_object('company_name',b.name,'region_code',b.region_code,'game_family',t.game_family,'can_manage',t.can_manage) order by e.hired_at desc) from public.business_employees e join public.businesses b on b.id=e.business_id left join public.business_role_templates t on t.id=e.role_template_id where e.profile_id=auth.uid()),'[]'::jsonb),'experience',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('level',least(20,1+x.experience/100))) from public.citizen_professional_experience x where profile_id=auth.uid()),'[]'::jsonb),'applications',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('company_name',b.name,'role',t.name) order by a.created_at desc) from public.business_applications a join public.business_vacancies v on v.id=a.vacancy_id join public.businesses b on b.id=v.business_id join public.business_role_templates t on t.id=v.role_template_id where a.profile_id=auth.uid()),'[]'::jsonb)) where auth.uid() is not null
$$;
create or replace function public.configure_company_operations(p_business_id uuid,p_region_code text,p_owner_operates boolean,p_price_multiplier numeric) returns void language plpgsql security definer set search_path='' as $$
declare b public.businesses%rowtype;
begin
 select * into b from public.businesses where id=p_business_id for update;
 if auth.uid() is null or b.owner_id is distinct from auth.uid() then raise exception 'Somente o proprietário pode definir a sede e a estratégia.' using errcode='42501';end if;
 if not exists(select 1 from public.economic_regions where code=p_region_code) or p_price_multiplier is null or p_price_multiplier not between .5 and 3 or p_owner_operates is null then raise exception 'Confira a sede, participação na operação e política de preços.';end if;
 update public.businesses set region_code=p_region_code,owner_operates=p_owner_operates,price_multiplier=p_price_multiplier,updated_at=now() where id=b.id;
end $$;
create or replace function public.get_company_management(p_business_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare b public.businesses%rowtype; result jsonb;
begin
 if not private.can_manage_company(p_business_id) then raise exception 'Acesso restrito à gestão desta empresa.' using errcode='42501';end if;
 select * into b from public.businesses where id=p_business_id;
 result:=jsonb_build_object('business',to_jsonb(b),'cash',(select balance from public.accounts where id=b.bank_account_id),
 'staff',coalesce((select jsonb_agg(to_jsonb(e) order by e.fired_at nulls first,e.hired_at) from public.business_employees e where e.business_id=b.id),'[]'::jsonb),
 'roles',coalesce((select jsonb_agg(to_jsonb(t) order by t.name) from public.business_role_templates t where t.business_type_id=b.business_type_id),'[]'::jsonb),
 'vacancies',coalesce((select jsonb_agg(to_jsonb(v) order by v.created_at desc) from public.business_vacancies v where v.business_id=b.id),'[]'::jsonb),
 'applications',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('full_name',p.full_name,'role',t.name,'level',least(20,1+coalesce(x.experience,0)/100)) order by a.created_at desc) from public.business_applications a join public.business_vacancies v on v.id=a.vacancy_id join public.business_role_templates t on t.id=v.role_template_id join public.profiles p on p.id=a.profile_id left join public.citizen_professional_experience x on x.profile_id=p.id and x.skill_area=t.skill_area where v.business_id=b.id),'[]'::jsonb),
 'inventory',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('name',r.name,'unit',r.unit,'base_price',r.base_price)) from public.business_inventory i join public.economic_resources r on r.code=i.resource_code where i.business_id=b.id),'[]'::jsonb),
 'recipes',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('resource_name',e.name)) from public.business_recipes r join public.economic_resources e on e.code=r.output_resource where r.business_type_id=b.business_type_id),'[]'::jsonb),
 'transactions',coalesce((select jsonb_agg(to_jsonb(t)) from (select * from public.business_transactions where business_id=b.id order by created_at desc limit 100) t),'[]'::jsonb),
 'cycles',coalesce((select jsonb_agg(to_jsonb(c)) from (select * from public.business_balance_cycles where business_id=b.id order by cycle_start_at desc limit 12) c),'[]'::jsonb));
 return result;
end $$;
revoke all on function public.manage_company_workforce(uuid,text,jsonb,uuid),public.apply_company_vacancy(uuid,text),public.get_company_jobs(),public.get_my_work(),public.configure_company_operations(uuid,text,boolean,numeric),public.get_company_management(uuid) from public,anon;
grant execute on function public.manage_company_workforce(uuid,text,jsonb,uuid),public.apply_company_vacancy(uuid,text),public.get_company_jobs(),public.get_my_work(),public.configure_company_operations(uuid,text,boolean,numeric),public.get_company_management(uuid) to authenticated;
create or replace function public.get_business_catalog(p_region_code text default 'DF') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare region public.economic_regions%rowtype; macro numeric; result jsonb;
begin
 if auth.uid() is null then raise exception 'Entre para consultar atividades empresariais.' using errcode='42501';end if;
 select * into region from public.economic_regions where code=p_region_code;
 if region.code is null then raise exception 'Selecione um estado válido para a estimativa.';end if;
 select coalesce((to_jsonb(s)->>'confidence_index')::numeric,50) into macro from public.economic_state s limit 1;
 macro:=greatest(.5,least(1.5,.8+coalesce(macro,50)/250));
 select coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object('registration_fee',(fee->>'buyer_tax')::numeric,'registration_quote',fee,'activity_restricted',(fee->>'restricted')::boolean,'estimate_low',round(estimate*.7,2),'estimate_high',round(estimate*1.3,2),'estimated_for_region',region.code,'estimate_period_days',7,'estimate_workforce',t.min_employees) order by t.name),'[]'::jsonb) into result
 from public.business_types t
 cross join lateral(select public.quote_legal_levies('license',0,true,t.economic_sector_id,t.id) fee) levy
 cross join lateral(select count(*) competitors from public.businesses b where b.business_type_id=t.id and b.status='active' and b.region_code=region.code) c
 cross join lateral(select coalesce(sum((input.value::numeric)*r.base_price),0) cost from public.business_recipes recipe cross join lateral jsonb_each_text(recipe.inputs) input join public.economic_resources r on r.code=input.key where recipe.business_type_id=t.id) input_cost
 cross join lateral(select coalesce((select r.base_price from public.business_recipes recipe join public.economic_resources r on r.code=recipe.output_resource where recipe.business_type_id=t.id limit 1),0) price) output
 cross join lateral(select 7*(t.base_daily_capacity*(output.price-input_cost.cost)*macro*(.75+(region.energy+region.roads+region.telecom)/1200)/(1+c.competitors*.03)-t.min_employees*300.0/7-t.daily_overhead) estimate) estimates
 where t.is_active;
 return result;
end $$;
revoke all on function public.get_business_catalog(text) from public,anon;
grant execute on function public.get_business_catalog(text) to authenticated;
CREATE OR REPLACE FUNCTION private.validate_legal_definition(p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d jsonb:=coalesce(p_data->'definition','{}'); k text;
BEGIN
 IF jsonb_typeof(d)<>'object' THEN RAISE EXCEPTION 'INVALID_LEGAL_MEASURE'; END IF;
 FOR k IN SELECT jsonb_object_keys(d) LOOP
   IF k NOT IN('basis','payer','nature','audience','min_amount','max_amount','exempt_below','sector_id','category','document_type','penal_code_id','minimum','maximum','fine','weekdays','hour_from','hour_until','budget','eligible_balance_max','discount_rate','discount_sector_id') THEN RAISE EXCEPTION 'UNSUPPORTED_LEGAL_PARAMETER'; END IF;
 END LOOP;
 IF d ? 'category' AND NOT EXISTS(SELECT 1 FROM public.products WHERE category=d->>'category') AND NOT (d->>'basis'='license' AND EXISTS(SELECT 1 FROM public.business_types WHERE id=d->>'category')) THEN RAISE EXCEPTION 'INVALID_LEGAL_CATEGORY'; END IF;
 IF d->>'basis'='document' AND (coalesce(d->>'document_type','') NOT IN('CNH','Passport','RG','CPF','CTD','CNPJ','Título de Eleitor','Certificado de Reservista','Certidão de Casamento','Registro Profissional')) THEN RAISE EXCEPTION 'INVALID_DOCUMENT_TYPE'; END IF;
 IF d ? 'discount_sector_id' AND NOT EXISTS(SELECT 1 FROM public.economic_sectors WHERE id=(d->>'discount_sector_id')::uuid) THEN RAISE EXCEPTION 'INVALID_LEGAL_SECTOR'; END IF;
 IF d ? 'discount_rate' AND ((d->>'discount_rate')::numeric NOT BETWEEN 0 AND 1 OR (d->>'discount_rate')::numeric::text IN('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'INVALID_LEGAL_VALUE'; END IF;
 IF d ? 'eligible_balance_max' AND ((d->>'eligible_balance_max')::numeric<0 OR (d->>'eligible_balance_max')::numeric::text IN('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'INVALID_LEGAL_VALUE'; END IF;
 IF p_data->>'kind'='benefit' AND (d ? 'category' OR d ? 'min_amount' OR d ? 'max_amount' OR d ? 'hour_from') THEN RAISE EXCEPTION 'UNSUPPORTED_LEGAL_PARAMETER'; END IF;
 IF d->>'basis'='transfer' AND (d ? 'sector_id' OR d->>'audience'='business') THEN RAISE EXCEPTION 'UNSUPPORTED_LEGAL_PARAMETER'; END IF;
 IF p_data->>'kind' IN('tax','fee') AND (d ? 'weekdays' OR d ? 'hour_from' OR d ? 'budget') THEN RAISE EXCEPTION 'UNSUPPORTED_LEGAL_PARAMETER'; END IF;
 IF p_data->>'kind' IN('tax','fee') AND d->>'basis' IN('license','document') AND d->>'nature'<>'fixed' THEN RAISE EXCEPTION 'INVALID_TAX_BASIS'; END IF;
END $function$
;
CREATE OR REPLACE FUNCTION private.register_business_authoritative(p_owner_id uuid, p_business_type_id text, p_company_name text, p_description text, p_idempotency_key uuid)
 RETURNS businesses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account public.accounts%rowtype;
  v_type public.business_types%rowtype;
  v_business public.businesses%rowtype;
  v_fee numeric;
  v_transaction uuid; v_quote jsonb;
begin
  if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
  select * into v_business from public.businesses where registration_idempotency_key=p_idempotency_key;
  if found then if v_business.owner_id IS DISTINCT FROM p_owner_id then raise exception 'IDEMPOTENCY_KEY_FORBIDDEN'; end if; return v_business; end if;
  if length(btrim(coalesce(p_company_name,'')))<5 or length(btrim(coalesce(p_description,'')))<15 then
    raise exception 'BUSINESS_DETAILS_INCOMPLETE';
  end if;
  select * into v_type from public.business_types where id=p_business_type_id and is_active for share;
  if not found then raise exception 'BUSINESS_TYPE_NOT_AVAILABLE'; end if;
  perform public.process_due_legal_effects();
  select * into v_account from public.accounts where user_id=p_owner_id for update;
  if not found then raise exception 'BANK_ACCOUNT_REQUIRED'; end if;
  v_quote:=public.quote_legal_levies('license',0,true,v_type.economic_sector_id,p_business_type_id);
  if (v_quote->>'restricted')::boolean then raise exception 'ACTIVITY_RESTRICTED_BY_LAW'; end if;
  v_fee:=(v_quote->>'buyer_tax')::numeric;
  if v_account.balance<v_fee then raise exception 'INSUFFICIENT_BALANCE'; end if;

    owner_id,business_type_id,name,description,status,employees,monthly_revenue,
    bank_account_id,registration_idempotency_key,economic_sector_id
  ) values(
    p_owner_id,p_business_type_id,btrim(p_company_name),btrim(p_description),'active',
    0,0,v_account.id,p_idempotency_key,v_type.economic_sector_id
  ) returning * into v_business;
  update public.accounts set balance=balance-v_fee,updated_at=clock_timestamp() where id=v_account.id;
  update public.government_finances set treasury_balance=treasury_balance+v_fee,updated_at=clock_timestamp() where id=1;
  values(v_account.id,v_fee,'Taxa de registro empresarial: '||v_business.name,'service_fee',
    jsonb_build_object('business_id',v_business.id,'business_type_id',p_business_type_id,'fee_type','business_registration','treasury_credit',true)||v_quote,
    p_idempotency_key) returning id into v_transaction;
  values(v_business.id,'registration',-v_fee,'Taxa de registro: '||v_business.name);
  if v_fee>0 then insert into public.government_revenues(revenue_type,source_table,source_id,actor_profile_id,business_id,amount,occurred_at_rp,metadata)
  values('fee','transactions',v_transaction::text,p_owner_id,v_business.id,v_fee,public.rp_now(),jsonb_build_object('kind','business_registration')); end if;
  values('business_registered','economy','businesses',v_business.id,p_owner_id,
    jsonb_build_object('businessName',v_business.name,'fee',v_fee,'transactionId',v_transaction),
    'business-registration:'||p_idempotency_key,'processed',clock_timestamp());
  return v_business;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.register_business_authoritative(p_owner_id uuid, p_business_type_id text, p_company_name text, p_description text, p_idempotency_key uuid, p_cnpj_id uuid DEFAULT NULL::uuid, p_brand jsonb DEFAULT '{}'::jsonb)
 RETURNS businesses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.businesses%rowtype; doc public.documents%rowtype;
begin
 if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
 select * into b from public.businesses where registration_idempotency_key=p_idempotency_key;
 if found then if b.owner_id<>p_owner_id then raise exception 'Operação não autorizada.'; end if; return b; end if;
 if not exists(select 1 from public.economic_regions where code=p_brand->>'region_code') then raise exception 'Selecione o estado da sede da empresa.';end if;
 if jsonb_typeof(coalesce(p_brand->'palette','[]'))<>'array' or jsonb_array_length(coalesce(p_brand->'palette','[]'))>3 or exists(select 1 from jsonb_array_elements_text(coalesce(p_brand->'palette','[]')) c where c!~'^#[0-9a-fA-F]{6}$') then raise exception 'Escolha até três cores válidas para a marca.';end if;
 if not coalesce(public.valid_brand_font(coalesce(p_brand->>'font_key','default')),false) or coalesce(p_brand->>'color','#64748B')!~'^#[0-9a-fA-F]{6}$' or (coalesce(p_brand->>'logo_url','')<>'' and p_brand->>'logo_url'!~'^https://') then raise exception 'Confira a personalização da empresa.'; end if;
 select * into doc from public.documents where id=p_cnpj_id and user_id=p_owner_id and type='CNPJ' and is_valid and (expires_at is null or expires_at>clock_timestamp()) for update;
 if (select requires_cnpj from public.business_types where id=p_business_type_id) and (doc.id is null or doc.metadata->>'business_type_id' is distinct from p_business_type_id) then raise exception 'Você precisa abrir um CNPJ compatível com esta atividade antes de criar a empresa.'; end if;
 if doc.id is not null and exists(select 1 from public.businesses where cnpj_document_id=doc.id) then raise exception 'Este CNPJ já está vinculado a uma empresa.'; end if;
 b:=private.register_business_authoritative(p_owner_id,p_business_type_id,p_company_name,p_description,p_idempotency_key);
 update public.businesses set region_code=p_brand->>'region_code',brand_palette=coalesce(p_brand->'palette','[]'),cnpj_document_id=doc.id,logo_url=nullif(p_brand->>'logo_url',''),font_key=coalesce(p_brand->>'font_key','default'),brand_color=coalesce(p_brand->>'color','#64748B') where id=b.id returning * into b;
 if doc.id is not null then update public.documents set metadata=coalesce(metadata,'{}')||jsonb_build_object('business_id',b.id) where id=doc.id; end if;
 return b;
end $function$
;
CREATE OR REPLACE FUNCTION public.update_company_brand(p_business_id uuid, p_brand jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.businesses%rowtype;
BEGIN
 SELECT * INTO b FROM public.businesses WHERE id=p_business_id FOR UPDATE;
 IF auth.uid() IS NULL OR b.owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Somente o proprietário pode personalizar a empresa.' USING errcode='42501'; END IF;
 IF NOT coalesce(public.valid_brand_font(p_brand->>'font_key'),false) OR coalesce(p_brand->>'color','')!~'^#[0-9a-fA-F]{6}$'
  OR (coalesce(p_brand->>'logo_url','')<>'' AND p_brand->>'logo_url'!~'^https://') THEN RAISE EXCEPTION 'Confira a fonte, a cor e a imagem da empresa.'; END IF;
 IF jsonb_typeof(coalesce(p_brand->'palette','[]'))<>'array' OR jsonb_array_length(coalesce(p_brand->'palette','[]'))>3 OR EXISTS(select 1 from jsonb_array_elements_text(coalesce(p_brand->'palette','[]')) c where c!~'^#[0-9a-fA-F]{6}$') THEN RAISE EXCEPTION 'Escolha até três cores válidas.';END IF;
 UPDATE public.businesses SET brand_palette=coalesce(p_brand->'palette','[]'),logo_url=nullif(p_brand->>'logo_url',''),font_key=p_brand->>'font_key',brand_color=p_brand->>'color' WHERE id=b.id;
 PERFORM public.justice_write_audit('business.brand_updated','business',b.id,jsonb_build_object('font_key',b.font_key,'color',b.brand_color,'logo_url',b.logo_url),p_brand,'Personalização empresarial.');
END; $function$
;
CREATE OR REPLACE FUNCTION public.get_company_page(p_business_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.businesses%rowtype;
begin
 if auth.uid() is null then raise exception 'Entre para consultar empresas.' using errcode='42501'; end if;
 select * into b from public.businesses where id=p_business_id;
 if not found then return null; end if;
 return jsonb_build_object('id',b.id,'name',b.name,'description',b.description,'status',b.status,'created_at',b.created_at,'business_type_id',b.business_type_id,'logo_url',b.logo_url,'font_key',b.font_key,'brand_color',b.brand_color,'owner_id',b.owner_id,'brand_palette',b.brand_palette,'region_code',b.region_code,'market_value',b.market_value,'size_class',b.size_class,'employees',b.employees,'reputation',b.reputation,'control_kind',b.control_kind,'operational_status',b.operational_status,'can_manage',private.can_manage_company(b.id),
 'owner',(select jsonb_build_object('id',id,'full_name',full_name,'avatar_url',avatar_url) from public.profiles where id=b.owner_id),
 'activity',(select name from public.business_types where id=b.business_type_id),'regularization_required',b.metadata->'cnpj_regularization_required',
 'products',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'image_url',p.image_url,'price',p.final_price)) from public.get_products_with_final_price() p where p.seller->>'business_id'=b.id::text),'[]'::jsonb),
 'cnpjs',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'number',d.document_number,'activity',coalesce(d.metadata->>'activity_name',t.name),'issued_at',d.issued_at,'is_valid',d.is_valid and (d.expires_at is null or d.expires_at>now()))) from public.documents d left join public.business_types t on t.id=d.metadata->>'business_type_id' where d.type='CNPJ' and (d.id=b.cnpj_document_id or d.metadata->>'business_id'=b.id::text)),'[]'::jsonb));
end $function$
;
alter publication supabase_realtime add table public.business_inventory,public.business_vacancies,public.business_applications,public.citizen_professional_experience;
notify pgrst,'reload schema';
commit;
